import glob, h5py, numpy as np

def decode(arr):
    if arr.dtype.kind in 'SU':
        return np.array([x.decode() if isinstance(x, (bytes, bytearray)) else str(x) for x in arr])
    if arr.dtype == object:
        return np.array([x.decode() if isinstance(x, (bytes, bytearray)) else str(x) for x in arr])
    return arr.astype(str)

files=sorted(glob.glob('/app/data/sub-*/*.nwb'))
counts={k:0 for k in ['recorded','no_early','resp','no_auto','no_free','no_stim','no_early_no_ignore','regular_plus_stim','regular']}
per={k:[] for k in counts}
for fp in files:
    with h5py.File(fp,'r') as f:
        cls=f['units']['classification'][:].astype(str)
        if np.sum(cls=='good')==0:
            continue
        nrec=f['units']['is_good_trials'].shape[1]
        tr=f['intervals']['trials']
        outcome=decode(tr['outcome'][:nrec])
        early=decode(tr['early_lick'][:nrec])
        auto=tr['auto_water'][:nrec].astype(int)
        free=tr['free_water'][:nrec].astype(int)
        stim_dur=decode(tr['photostim_duration'][:nrec])
        stim=np.array([s!='N/A' for s in stim_dur])
        masks={
            'recorded': np.ones(nrec,dtype=bool),
            'no_early': early=='no early',
            'resp': outcome!='ignore',
            'no_auto': auto==0,
            'no_free': free==0,
            'no_stim': ~stim,
            'no_early_no_ignore': (early=='no early') & (outcome!='ignore'),
            'regular_plus_stim': (early=='no early') & (auto==0) & (free==0) & (outcome!='ignore'),
            'regular': (early=='no early') & (auto==0) & (free==0) & (outcome!='ignore') & (~stim),
        }
        for k,m in masks.items():
            c=int(m.sum())
            counts[k]+=c
            per[k].append(c)
for k in counts:
    print(k, counts[k], float(np.mean(per[k])))
